// ========================================================
// ヘルパー関数 (共通処理・ランダム化処理)
// ========================================================

/**
* 配列をランダムにシャッフル (Fisher-Yates)
*/
function shuffleArray(arr) {
const newArr = [...arr];
for (let i = newArr.length - 1; i > 0; i--) {
const j = Math.floor(Math.random() * (i + 1));
[newArr[i], newArr[j]] = [newArr[j], newArr[i]];
}
return newArr;
}

/**
* 選択肢テキストから前頭の番号記号（「1) 」「1. 」等）を除去する
*/
function cleanOptionText(text) {
if (typeof text !== 'string') return text;
return text.replace(/^[0-9]+[\)\.\s]\s*/, "").trim();
}

/**
* 単一問題の選択肢をシャッフルし、正解インデックス・回答を再構成する
*/
function randomizeOptions(questionObj) {
if (!questionObj.opts || questionObj.opts.length <= 1) {
return { ...questionObj };
}

const rawAnswers = Array.isArray(questionObj.a)
? questionObj.a
: [questionObj.a];

const rawOptions = questionObj.opts.map((optionText) => {
const cleaned = cleanOptionText(optionText);
const isCorrect = rawAnswers.some(ans => {
if (typeof ans === 'number') {
return questionObj.opts[ans] === optionText;
}
return cleanOptionText(ans) === cleaned;
});
return {
text: cleaned,
isCorrect: isCorrect
};
});

const shuffledRawOptions = shuffleArray(rawOptions);

const newOptions = [];
const newAnswers = [];

shuffledRawOptions.forEach((item, index) => {
newOptions.push(item.text);
if (item.isCorrect) {
newAnswers.push(index);
}
});

return {
...questionObj,
opts: newOptions,
a: newAnswers.length === 1 ? newOptions[newAnswers[0]] : newAnswers.map(i => newOptions[i]),
answers: newAnswers
};
}

/**
* 指定された回（lessonNum）の問題セットを取得する
* - "all" や 99 等が指定された場合は、1〜10回すべての問題を統合してシャッフルし「総合練習問題」として返す
*/
function getQuestionSet(lessonNum, shouldRandomize = true) {
let questions = [];

if (lessonNum === 'all' || lessonNum === 99 || lessonNum === '総合') {
// 全回（第1回〜第10回）の全問題を1つの配列に統合
Object.keys(quizData).forEach(key => {
if (Array.isArray(quizData[key])) {
questions = questions.concat(quizData[key]);
}
});
} else if (quizData[lessonNum]) {
questions = [...quizData[lessonNum]];
} else {
console.warn(`Lesson ${lessonNum} が見つかりません。`);
return [];
}

// 順序のランダム化
if (shouldRandomize) {
questions = shuffleArray(questions);
questions = questions.map(q => randomizeOptions(q));
}

return questions;
}

// ========================================================
// グローバル空間（window.QUIZ_DB）への登録・互換性維持
// ========================================================
if (typeof window !== 'undefined') {
window.QUIZ_DB = window.QUIZ_DB || {};

// フラットな全問リスト（回情報付与）を生成して保存
let allQuestionsFlat = [];
Object.keys(quizData).forEach(roundKey => {
const list = quizData[roundKey].map(q => ({
...q,
round: parseInt(roundKey, 10),
options: q.opts || [],
answers: Array.isArray(q.a) ? q.a : [q.a]
}));
allQuestionsFlat = allQuestionsFlat.concat(list);
});

window.QUIZ_DB["nursing_method"] = allQuestionsFlat;
window.QUIZ_DB["看護方法論Ⅰ"] = allQuestionsFlat;

// 関数群の公開
window.nursingQuiz = {
quizData,
getQuestionSet,
shuffleArray,
randomizeOptions
};
}

